const split = (s: string) => s.split(/\s+/).filter(Boolean);

/** Vanilla block texture names (relative, e.g. "grass_block_top"). */
export const VANILLA_BLOCK_TEXTURES = new Set(split(BLOCK_TEXTURES));
/** Vanilla item ids (also serve as item texture names item/<id> and item-def names). */
export const VANILLA_ITEM_ID_LIST = new Set(split(ITEM_IDS));
/** Vanilla block ids (blockstate + block-model override names). */
export const VANILLA_BLOCK_ID_LIST = new Set(split(BLOCK_IDS));

/** Is a texture path (e.g. "block/stone", "item/diamond_sword") a vanilla texture? */
export function isVanillaTexturePath(rel: string) {
  if (rel.startsWith("block/")) return VANILLA_BLOCK_TEXTURES.has(rel.slice(6));
  if (rel.startsWith("item/")) return VANILLA_ITEM_ID_LIST.has(rel.slice(5));
  return false;
}
